{"packet_id":"D076-01","doc_id":"D076","jurisdiction":"San Diego, CA","category":"algorithmic_rent_setting","lifecycle":"pending_bill","title":"Prohibition of Anti-Competitive Automated Rent Price-Fixing Ordinance","requirement":"Would prohibit any person from selling, licensing, or otherwise providing an algorithmic device to a landlord, and would prohibit a landlord from using an algorithmic device to set rental rates or occupancy levels for residential rental property.","key_value":"up to $1,000 per violation","coverage_conditions":"Residential rental property in the City of San Diego; applies to any person selling or providing algorithmic devices and to landlords using them.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rental property in the City of San Diego"},"exemptions":"Excludes software publishing reports from aggregated historical nonpublic competitor data more than 90 days old or from public information, if it does not recommend future rates, and software setting rates or income limits under affordable housing program guidelines.","penalty":"Tenant may seek injunctive relief, damages, or civil penalties up to $1,000 per violation; prevailing tenant recovers costs and reasonable attorney's fees.","effective_date":null,"citation":"San Diego Mun. Code §§98.1101–98.1104","quoted_span":"(a) It is unlawful for a person to sell, license, or otherwise provide an
algorithmic device to a landlord.
(b) It is unlawful for a landlord to use an algorithmic device to set rental rates
or occupancy levels for residential rental property.","interaction":null,"confidence":0.6,"conflict_flag":false,"conflict_note":"No final passage date appears; ordinance would take effect 30 days after final passage."}
